@Component("campaign-handler")
@ProcessingGroup("campaign-processing-group")
public class CampaignEventHandler {
	
	// core constructor
	CampaignEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCampaignEvent
     */
    @EventHandler
    public void handle( CreateCampaignEvent event) {
        entityManager.persist(new Campaign(event.getCampaignId(), event.getName(), event.getStartDate(), event.getEndDate(), event.getBudget(), event.getActualCost(), event.getExpectedRevenue(), event.getOrganization(), event.getParentCampaign(), event.getChildCampaigns(), event.getMembers(), event.getOpportunities(), event.getAccounts(), event.getLeads(), event.getContacts(), event.getTeams(), event.getActivities(), event.getStatus(), event.getType()));
    }

    /*
     * @param	event UpdateCampaignEvent
     */
    @EventHandler
    public Campaign handle( UpdateCampaignEvent event) {
    	entityManager.merge(new Campaign(event.getCampaignId(), event.getName(), event.getStartDate(), event.getEndDate(), event.getBudget(), event.getActualCost(), event.getExpectedRevenue(), event.getOrganization(), event.getParentCampaign(), event.getChildCampaigns(), event.getMembers(), event.getOpportunities(), event.getAccounts(), event.getLeads(), event.getContacts(), event.getTeams(), event.getActivities(), event.getStatus(), event.getType()));
    }
    
    /*
     * @param	event DeleteCampaignEvent
     */
    @EventHandler
    public void on( DeleteCampaignEvent event) {
    	Campaign entity = new Campaign();
   
    	// ------------------------------------------
    	// apply the CampaignId
    	// ------------------------------------------
    	entity.setCampaignId( event.getCampaignId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CampaignRepository campaignEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CampaignEventHandler.class.getName());

}
